class Solution {
    public int coinChange(int[] coins, int amount) {
        int result = fewestCoins(coins, amount);
        return result == Integer.MAX_VALUE ? -1 : result;
    }

    private int fewestCoins(int[] coins, int remaining) {
        if (remaining == 0) return 0;
        if (remaining < 0) return Integer.MAX_VALUE;
        int best = Integer.MAX_VALUE;
        for (int coin : coins) {
            int subproblem = fewestCoins(coins, remaining - coin);
            if (subproblem != Integer.MAX_VALUE) {
                best = Math.min(best, subproblem + 1);
            }
        }
        return best;
    }
}

